function missingSeqs(lastShownSeq, receivedSeqs) {
  const got = new Set(receivedSeqs.filter((s) => s > lastShownSeq));
  if (got.size === 0) return [];
  const max = Math.max(...got);
  const missing = [];
  for (let s = lastShownSeq + 1; s < max; s++) {
    if (!got.has(s)) missing.push(s);
  }
  return missing;
}

missingSeqs(10, [14, 12, 11]); // [13]
missingSeqs(10, [9, 10]);      // []
